CREATE TRIGGER CDN.KntKartyAlias_DeleteHandler ON CDN.KntKarty FOR DELETE AS SET NOCOUNT ON
-- obsługa sprawdzania relacji restrict do tabeli CDN.UmwNag IF EXISTS ( SELECT * FROM CDN.UmwNag, deleted WHERE deleted.Knt_GIDNumer = CDN.UmwNag.UmN_KnDNumer AND (CDN.UmwNag.UmN_KnDTyp=32) ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą UmwNag) [KntKartyAlias_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ReklNag IF EXISTS ( SELECT * FROM CDN.ReklNag, deleted WHERE deleted.Knt_GIDNumer = CDN.ReklNag.RLN_KnDNumer
) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Nie można usunąć kontrahenta. Kontrahent jest ustawiony jako docelowy na reklamacji./# [KntKartyAlias_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.PrjStruktura IF EXISTS ( SELECT * FROM CDN.PrjStruktura, deleted WHERE deleted.Knt_GIDNumer = CDN.PrjStruktura.PRJ_KndNumer
) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Nie można usunąć kontrahenta. Kontrahent jest ustawiony jako docelowy na projekcie./# [KntKartyAlias_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.Zapisy IF EXISTS ( SELECT * FROM CDN.Zapisy, deleted WHERE deleted.Knt_GIDNumer = CDN.Zapisy.KAZ_KNDNumer
) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Nie można usunąć kontrahenta. Kontrahent jest ustawiony jako docelowy na zapisie kasowo-bankowym./# [KntKartyAlias_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.MemNag IF EXISTS ( SELECT * FROM CDN.MemNag, deleted WHERE deleted.Knt_GIDNumer = CDN.MemNag.MEN_KNDNumer
