) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Nie można usunąć kontrahenta. Kontrahent jest ustawiony jako docelowy na pozycji noty memoriałowej./# [KntKartyAlias_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.SrwZlcNag IF EXISTS ( SELECT * FROM CDN.SrwZlcNag, deleted WHERE deleted.Knt_GIDTyp = CDN.SrwZlcNag.SZN_KnDTyp AND deleted.Knt_GIDNumer = CDN.SrwZlcNag.SZN_KnDNumer AND (CDN.SrwZlcNag.SZN_KnDTyp=32) ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą SrwZlcNag) [KntKartyAlias_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ProdZlecenia IF EXISTS ( SELECT * FROM CDN.ProdZlecenia, deleted WHERE deleted.Knt_GIDNumer = CDN.ProdZlecenia.PZL_KnDNumer
AND (CDN.ProdZlecenia.PZL_KnDTyp=32) ) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Nie można usunąć kontrahenta. Kontrahent jest ustawiony jako docelowy na zleceniu produkcyjnym./# [KntKartyAlias_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ProdTechnologia IF EXISTS ( SELECT * FROM CDN.ProdTechnologia, deleted WHERE deleted.Knt_GIDNumer = CDN.ProdTechnologia.PTE_KnDNumer
