eją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą SadNag) [KntKartyAlias_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.TraNag IF EXISTS ( SELECT * FROM CDN.TraNag, deleted WHERE deleted.Knt_GIDNumer = CDN.TraNag.TrN_AkwNumer AND (CDN.TraNag.TRN_AkwTyp=32) ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą TraNag) [KntKartyAlias_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ZamNag IF EXISTS ( SELECT * FROM CDN.ZamNag, deleted WHERE deleted.Knt_GIDNumer = CDN.ZamNag.ZaN_AkwNumer AND (CDN.ZamNag.ZaN_AkwTyp=32) ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą ZamNag) [KntKartyAlias_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ZRNMaterialy IF EXISTS ( SELECT * FROM CDN.ZRNMaterialy, deleted WHERE deleted.Knt_GIDNumer = CDN.ZRNMaterialy.ZRM_KntNumerO ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą ZRNMaterialy) [KntKartyAlias_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ZlcRemElem IF EXISTS ( SELECT * FROM CDN.ZlcRemElem, deleted WHERE deleted.Knt_GIDNumer = CDN.ZlcRemElem.ZRE_KNTNumerO ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą ZlcRemElem) [KntKartyAlias_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ZlcRemNag IF EXISTS ( SELECT * FROM CDN.ZlcRemNag, deleted WHERE deleted.Knt_GIDNumer = CDN.ZlcRemNag.ZRN_KNTNumerO ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą ZlcRemNag) [KntKartyAlias_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.SrsObiekty IF EXISTS ( SELECT * FROM CDN.SrsObiekty, deleted WHERE deleted.Knt_GIDNumer = CDN.SrsObiekty.SOb_KntNumerW ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą SrsObiekty) [KntKartyAlias_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.CRMKntEtapy IF EXISTS ( SELECT * FROM CDN.CRMKntEtapy, deleted WHERE deleted.Knt_GIDNumer = CDN.CRMKntEtapy.CEK_AkwNumer
AND (CDN.CRMKntEtapy.CEK_AkwTyp=32) ) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Nie można usunąć kontrahenta. Kontrahent jest akwizytorem w etapie kampani CRM./# [KntKartyAlias_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ZlcNag IF EXISTS ( SELECT * FROM CDN.ZlcNag, deleted WHERE deleted.Knt_GIDNumer = CDN.ZlcNag.ZcN_KnDNumer ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą ZlcNag) [KntKartyAlias_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.KntKarty IF EXISTS ( SELECT * FROM CDN.KntKarty, deleted WHERE deleted.Knt_GIDNumer = CDN.KntKarty.Knt_AkwNumer
AND (CDN.KntKarty.Knt_AkwTyp=32) ) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Nie można usunąć kontrahenta. Kontrahent jest akwizytorem innego kontrahenta./# [KntKartyAlias_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ProdZlecElem IF EXISTS ( SELECT * FROM CDN.ProdZlecElem, deleted WHERE deleted.Knt_GIDNumer = CDN.ProdZlecElem.PZE_KnDNumer
AND (CDN.ProdZlecElem.PZE_KnDTyp=32) ) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Nie można usunąć kontrahenta. Kontrahent jest ustawiony jako docelowy na pozycji zlecenia produkcyjnego./# [KntKartyAlias_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ProdNadzlecenia IF EXISTS ( SELECT * FROM CDN.ProdNadzlecenia, deleted WHERE deleted.Knt_GIDNumer = CDN.ProdNadzlecenia.PNZ_KnDNumer AND (CDN.ProdNadzlecenia.PNZ_KnDTyp = 32) ) BEGIN RAISERROR('Istnieją zapisy powiązane z modyfikowanym rekordem (powiązanie z tabelą ProdNadzlecenia) [KntKartyAlias_DeleteHandler]. ', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END
-- obsługa kaskadowego kasowania wierszy z tabeli CDN.PDOCzynnosci IF EXISTS(SELECT * FROM CDN.PDOCzynnosci, deleted WHERE deleted.Knt_GIDNumer = CDN.PDOCzynnosci.PDOC_PrzedstNumer AND (CDN.PDOCzynnosci.PDOC_PrzedstTyp=32) ) DELETE CDN.PDOCzynnosci FROM CDN.PDOCzynnosci, deleted WHERE deleted.Knt_GIDNumer = CDN.PDOCzynnosci.PDOC_PrzedstNumer AND (CDN.PDOCzynnosci.PDOC_PrzedstTyp=32)
SET NOCOUNT OFF

CREATE TRIGGER CDN.KntOsobyAlias_DeleteHandler ON CDN.KntOsoby FOR DELETE AS SET NOCOUNT ON
-- obsługa sprawdzania relacji restrict do tabeli CDN.SrwZlcNag IF EXISTS ( SELECT * FROM CDN.SrwZlcNag, deleted WHERE deleted.KnS_KntTyp = CDN.SrwZlcNag.SZN_KnSTypD AND deleted.KnS_KntNumer = CDN.SrwZlcNag.SZN_KnSNumerD AND deleted.KnS_KntLp = CDN.SrwZlcNag.SZN_KnSLpD
AND (CDN.SrwZlcNag.SZN_KnSTypD=32) ) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Nie można usunąć osoby. Usuwana osoba jest wybrana na jednym z dokumentów zlecenia serwisowego./# [KntOsobyAlias_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ImpNag IF EXISTS ( SELECT * FROM CDN.ImpNag, deleted WHERE deleted.KnS_KntNumer = CDN.ImpNag.ImN_KnSNumerD AND deleted.KnS_KntLp = CDN.ImpNag.ImN_KnSLpD
) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Nie można usunąć osoby. Usuwana osoba jest wybrana na jednym z dokumentów handlowych./# [KntOsobyAlias_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.TraNag IF EXISTS ( SELECT * FROM CDN.TraNag, deleted WHERE deleted.KnS_KntNumer = CDN.TraNag.TrN_KnSNumerD AND deleted.KnS_KntLp = CDN.TraNag.TrN_KnSLpD
) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Nie można usunąć osoby. Usuwana osoba jest wybrana na jednym z dokumentów handlowych./# [KntOsobyAlias_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.ZamNag IF EXISTS ( SELECT * FROM CDN.ZamNag, deleted WHERE deleted.KnS_KntTyp = CDN.ZamNag.ZaN_KnSTypP AND deleted.KnS_KntNumer = CDN.ZamNag.ZaN_KnSNumerP AND deleted.KnS_KntLp = CDN.ZamNag.ZaN_KnSLpP
) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Nie można usunąć osoby. Usuwana osoba jest wybrana na jednym z dokumentów zamówień./# [KntOsobyAlias_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END -- obsługa sprawdzania relacji restrict do tabeli CDN.CRMKntEtapy IF EXISTS ( SELECT * FROM CDN.CRMKntEtapy, deleted WHERE deleted.KnS_KntNumer = CDN.CRMKntEtapy.CEK_KntNumer AND deleted.KnS_KntLp = CDN.CRMKntEtapy.CEK_KntOsobaLp
AND (CDN.CRMKntEtapy.CEK_AkwTyp=32 AND CDN.CRMKntEtapy.CEK_AkwOsobaLp>0) ) BEGIN RAISERROR('#CDN_BLAD/##CDN_1=Nie można usunąć osoby. Usuwana osoba jest wybrana na jednej z kampanii marketingowej./# [KntOsobyAlias_DeleteHandler]', 16, 1) ROLLBACK TRAN SET NOCOUNT OFF RETURN END
-- obsługa kaskadowego kasowania wierszy z tabeli CDN.PDOCzynnosci IF EXISTS(SELECT * FROM CDN.PDOCzynnosci, deleted WHERE deleted.KnS_KntNumer = CDN.PDOCzynnosci.PDOC_PrzedstNumer AND deleted.KnS_KntLp = CDN.PDOCzynnosci.PDOC_PrzedstLp AND (CDN.PDOCzynnosci.PDOC_PrzedstTyp=32 AND CDN.PDOCzynnosci.PDOC_PrzedstLp>0) ) DELETE CDN.PDOCzynnosci FROM CDN.PDOCzynnosci, deleted WHERE deleted.KnS_KntNumer = CDN.PDOCzynnosci.PDOC_PrzedstNumer AND deleted.KnS_KntLp = CDN.PDOCzynnosci.PDOC_PrzedstLp AND (CDN.PDOCzynnosci.PDOC_PrzedstTyp=32 AND CDN.PDOCzynnosci.PDOC_PrzedstLp>0)
SET NOCOUNT OFF

